-- Add lat/lng to venues so they can be plotted on a map. Coordinates are
-- approximate city/state centers (this is placeholder venue data, not real
-- addresses). City-tagged venues get their city's coordinates; the
-- state-level venues (no specific city) get that state's primary city as
-- an approximate anchor point.
alter table venues add column if not exists latitude numeric;
alter table venues add column if not exists longitude numeric;

